function achievementReportCheck(name:string,run:(f:Awaited<ReturnType<typeof achievementReportFixture>>)=>Promise<void>){test(name,async()=>{const f=await achievementReportFixture();try{await run(f);}finally{await f.pg.close();}});}
async function achievementBackground(f:Pick<A,'pg'|'a'>,schedule=false){const errors:{code?:string;message?:string}[]=[],database:Database={async connect(){const c=f.pg.runtime?await f.pg.runtime.connect():{query:f.pg.query.bind(f.pg),release(){}};await c.query('SET ROLE kavosh_automation_worker');return {async query<Row>(sql:string,p?:unknown[]){try{return await c.query<Row>(sql,p);}catch(error){const e=error as {code?:string;message?:string};errors.push({code:e.code,message:e.message});throw error;}},release(destroy?:boolean){c.release(destroy);}};}};try{return {...await(schedule?processOneReportSchedule:processOneReport)(database,[f.a]),errors};}finally{if(!f.pg.runtime)await f.pg.exec('RESET ROLE');}}
achievementReportCheck('queued achievement exports use the real worker and private same-snapshot record manifest without financial grants',async f=>{
 const award=await f.issue();assert.equal(award.response.status,201);const q=await f.request('reports/jobs',{reportId:'community.achievements',parameters:{from:'2026-01-01',through:'2026-01-31'}},'manager');assert.equal(q.response.status,202,JSON.stringify(q.body));assert.equal(q.body.resultAvailable,false);const run=await achievementBackground(f);assert.equal(run.outcome,'succeeded',JSON.stringify(run));const path='reports/jobs/'+q.body.data.id,file=await f.request(path+'/download',undefined,'manager');assert.equal(file.response.status,200,JSON.stringify(file.body));const rows=parse(file.body,{bom:true,columns:true}) as Record<string,string>[];assert.equal(rows.find(r=>r.section==='total')?.awards,'1');const proof=(await f.pg.query('SELECT authorization_context FROM public.report_job_results WHERE job_id=$1',[q.body.data.id])).rows[0].authorization_context;assert.deepEqual(proof,{kind:'achievement_summary',sources:[{awardId:award.body.data.id,studentId:f.student,hubId:f.hub,classId:f.c.id}]});for(const value of [file.body,JSON.stringify((await f.report()).body),JSON.stringify((await f.request(path,undefined,'manager')).body)])assert.doesNotMatch(value,/authorizationContext|achievement_summary|PRIVATE|Built a first|guardian|dateOfBirth/);assert.equal((await f.request(path+'/download',undefined,'peer')).response.status,404);assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,0);assert.equal((await f.request('reports/finance/trial-balance?through=2026-01-31',undefined,'manager')).response.status,403);
});
