achievementReportCheck('a reviewed achievement schedule queues once under its real owner and retains schedule provenance in the generated CSV',async f=>{
 const due=new Date(Math.floor(Date.now()/60000)*60000-60000).toISOString(),earnedOn=(await f.pg.query<{on:string}>("SELECT (date_trunc('month',$1::timestamptz AT TIME ZONE 'America/Toronto')-interval '1 day')::date::text AS on",[due])).rows[0].on;assert.equal((await f.issue({...f.awardInput,earnedOn})).response.status,201);for(const cap of ['report-schedules.view','report-schedules.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow')",[f.a,f.managerRole,cap]);const preset=await f.request('reports/presets',{anchor:{kind:'hub',id:f.hub},definition:{name:'Recurring achievement CSV',reportId:'community.achievements',parameters:{},dateWindow:{kind:'previous_month',timeZone:'America/Toronto'}},reason:'Real scheduled report source'});assert.equal(preset.response.status,201);const at=due.slice(11,16),q=await f.request('reports/presets/'+preset.body.data.id+'/schedules',{definition:{name:'Owner scheduled achievements',presetVersion:1,timing:{timeZone:'UTC',localTime:at,startsOn:due.slice(0,10),cycle:{kind:'daily'},maxDelayMinutes:60}},reason:'Reviewed recurring generation'},'manager');assert.equal(q.response.status,202,JSON.stringify(q.body));const approved=await f.approve(q.body.approval.id);assert.equal(approved.response.status,200,JSON.stringify(approved.body));const id=approved.body.data.id;
 // Owner-only clock staging of the approved daily occurrence,not runtime
 // authority to edit schedule clocks or evidence of a deployed scheduler.
 await f.pg.exec('ALTER TABLE public.report_schedules DISABLE TRIGGER report_schedule_header_guard');try{await f.pg.query('UPDATE public.report_schedules SET next_due_at=$2 WHERE id=$1',[id,due]);}finally{await f.pg.exec('ALTER TABLE public.report_schedules ENABLE TRIGGER report_schedule_header_guard');}const scheduled=await achievementBackground(f,true);assert.equal(scheduled.outcome,'queued',JSON.stringify(scheduled));assert.equal((await achievementBackground(f,true)).claimed,false);const job=(await f.pg.query('SELECT id,requester_id FROM public.report_jobs')).rows[0];assert.equal(job.requester_id,f.actors.manager.person);const result=await achievementBackground(f);assert.equal(result.outcome,'succeeded',JSON.stringify(result));const file=await f.request('reports/jobs/'+job.id+'/download',undefined,'manager');assert.equal(file.response.status,200);const rows=parse(file.body,{bom:true,columns:true}) as Record<string,string>[],meta=Object.fromEntries(rows.filter(r=>r.section==='metadata').map(r=>[r.field,r.value]));assert.equal(meta.scheduleId,id);assert.equal(Date.parse(meta.scheduledFor),Date.parse(due));assert.equal(meta.dateWindowKind,'previous_month');assert.equal(Date.parse(meta.dateWindowResolvedAt),Date.parse(due));assert.equal(JSON.parse(meta.filters).through,earnedOn);assert.equal(rows.find(r=>r.section==='total')?.awards,'1');assert.equal((await f.pg.query('SELECT * FROM public.report_schedule_occurrences')).rows.length,1);
});
achievementReportCheck('native achievement completion rejects a financial-only manifest atomically and a cancelled queue cannot save an attachment',async f=>{
 assert.equal((await f.issue()).response.status,201);const q=await f.request('reports/jobs',{reportId:'community.achievements',parameters:{from:'2026-01-01',through:'2026-01-31'}});assert.equal(q.response.status,202);await f.pg.exec('BEGIN;SET LOCAL ROLE kavosh_automation_worker');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);const lease=(await f.pg.query<{lease_token:string}>('SELECT * FROM public.claim_report_job($1)',[[f.a]])).rows[0];assert.ok(lease);await assert.rejects(f.pg.query("SELECT public.finish_report_job($1,$2,'succeeded',NULL,'wrong proof','achievement.csv',$3::jsonb)",[q.body.data.id,lease.lease_token,JSON.stringify({hubIds:[f.hub],includesGlobal:false})]),/REPORT_RESULT_CONTEXT_INVALID/);}finally{await f.pg.exec('ROLLBACK');}assert.equal((await f.pg.query('SELECT * FROM public.report_job_results')).rows.length,0);assert.equal((await achievementBackground(f)).outcome,'succeeded');const second=await f.request('reports/jobs',{reportId:'community.achievements',parameters:{from:'2026-01-01',through:'2026-01-31'}});assert.equal(second.response.status,202);assert.equal((await f.request('reports/jobs/'+second.body.data.id+'/cancel',{})).response.status,200);assert.equal((await achievementBackground(f)).claimed,false);assert.equal((await f.pg.query('SELECT * FROM public.report_job_results WHERE job_id=$1',[second.body.data.id])).rows.length,0);
});
